    case localized_string_id::SAVESTATE_FAILED_DUE_TO_MISSING_SPU_SETTING: text = "SaveState failed: Failed to lock SPU state, enabling SPU-Compatible mode may fix it."; break;
    case localized_string_id::SAVESTATE_FAILED_DUE_TO_SPU: text = "SaveState failed: Failed to lock SPU state, using SPU ASMJIT will fix it."; break;
